CREATE TABLE hosted_metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL) STRICT;
CREATE TABLE sessions(id TEXT PRIMARY KEY,owner_scope TEXT NOT NULL UNIQUE,token_digest TEXT NOT NULL UNIQUE,signing_key_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('active','revoked','expired')),created_at INTEGER NOT NULL,last_seen_at INTEGER NOT NULL,expires_at INTEGER NOT NULL CHECK(expires_at>created_at),revoked_at INTEGER,revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0)) STRICT;
CREATE TABLE credentials(id TEXT PRIMARY KEY,owner_scope TEXT NOT NULL,provider TEXT NOT NULL CHECK(provider='nebius-token-factory'),label TEXT NOT NULL,secret_ciphertext TEXT,nonce TEXT,auth_tag TEXT,encryption_key_id TEXT,fingerprint TEXT NOT NULL,display_hint TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('unverified','verified','invalid','revoked','unavailable')),verified_at INTEGER,last_checked_at INTEGER,revoked_at INTEGER,verification_error_code TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),UNIQUE(owner_scope,id),FOREIGN KEY(owner_scope) REFERENCES sessions(owner_scope)) STRICT;
CREATE INDEX credentials_owner ON credentials(owner_scope,created_at,id);
CREATE INDEX credentials_fingerprint ON credentials(fingerprint,status);
CREATE TABLE campaigns(id TEXT PRIMARY KEY,owner_scope TEXT NOT NULL,credential_id TEXT NOT NULL,model_id TEXT NOT NULL,benchmark_id TEXT NOT NULL,harness_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('queued','running','pausing','paused','waiting','stopping','stopped','completed','failed')),wait_reason TEXT CHECK(wait_reason IN ('compute_budget','inference_budget','provider_quota','provider_auth','pricing_unavailable','global_capacity','reconciliation','credential_revoked','runtime_unavailable','challenge_required','operator_hold')),desired_control TEXT NOT NULL CHECK(desired_control IN ('run','pause','stop')),control_revision INTEGER NOT NULL DEFAULT 1,event_sequence INTEGER NOT NULL DEFAULT 0 CHECK(event_sequence>=0),compute_account_id TEXT NOT NULL,inference_account_id TEXT NOT NULL,accepted_pricing_snapshot_id TEXT,pricing_consent_revision INTEGER NOT NULL DEFAULT 1,config_json TEXT NOT NULL,checkpoint_json TEXT NOT NULL DEFAULT '{}',request_digest TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),UNIQUE(owner_scope,id),FOREIGN KEY(owner_scope,credential_id) REFERENCES credentials(owner_scope,id)) STRICT;
CREATE UNIQUE INDEX campaigns_active_owner ON campaigns(owner_scope) WHERE status IN ('queued','running','pausing','paused','waiting','stopping');
CREATE INDEX campaigns_owner ON campaigns(owner_scope,updated_at,id);
CREATE TABLE jobs(id TEXT PRIMARY KEY,owner_scope TEXT NOT NULL,campaign_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('campaign_run','campaign_reconcile','campaign_cleanup')),state TEXT NOT NULL CHECK(state IN ('queued','leased','running','waiting','completed','cancelled','failed')),payload_json TEXT NOT NULL DEFAULT '{}',checkpoint_json TEXT NOT NULL DEFAULT '{}',available_at INTEGER NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,lease_owner TEXT,lease_fence INTEGER NOT NULL DEFAULT 0,lease_expires_at INTEGER,heartbeat_at INTEGER,attempt_count INTEGER NOT NULL DEFAULT 0,max_attempts INTEGER NOT NULL DEFAULT 100,last_error_code TEXT,last_error_message TEXT,revision INTEGER NOT NULL DEFAULT 1,UNIQUE(owner_scope,campaign_id,id),FOREIGN KEY(owner_scope,campaign_id) REFERENCES campaigns(owner_scope,id)) STRICT;
CREATE UNIQUE INDEX jobs_unfinished_run ON jobs(campaign_id) WHERE kind='campaign_run' AND state IN ('queued','leased','running','waiting');
CREATE INDEX jobs_claim ON jobs(state,available_at,lease_expires_at,id);
CREATE TABLE budget_accounts(id TEXT PRIMARY KEY,owner_scope TEXT NOT NULL,campaign_id TEXT,credential_id TEXT,kind TEXT NOT NULL CHECK(kind IN ('platform_compute','campaign_compute','campaign_inference')),hard_limit_usd_micros INTEGER NOT NULL CHECK(hard_limit_usd_micros>=0),admission_limit_usd_micros INTEGER NOT NULL CHECK(admission_limit_usd_micros>=0 AND admission_limit_usd_micros<=hard_limit_usd_micros),settled_usd_micros INTEGER NOT NULL DEFAULT 0 CHECK(settled_usd_micros>=0),reserved_usd_micros INTEGER NOT NULL DEFAULT 0 CHECK(reserved_usd_micros>=0),unknown_reservation_count INTEGER NOT NULL DEFAULT 0 CHECK(unknown_reservation_count>=0),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','blocked','closed')),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,UNIQUE(kind,campaign_id),UNIQUE(owner_scope,id),FOREIGN KEY(owner_scope,campaign_id) REFERENCES campaigns(owner_scope,id),FOREIGN KEY(owner_scope,credential_id) REFERENCES credentials(owner_scope,id)) STRICT;
CREATE UNIQUE INDEX platform_compute_singleton ON budget_accounts(kind) WHERE kind='platform_compute';
CREATE TABLE budget_reservations(id TEXT PRIMARY KEY,owner_scope TEXT NOT NULL,campaign_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('compute','inference')),operation_id TEXT NOT NULL,operation_key TEXT NOT NULL,operation_kind TEXT NOT NULL,parent_reservation_id TEXT,amount_usd_micros INTEGER NOT NULL CHECK(amount_usd_micros>0),allocated_usd_micros INTEGER NOT NULL DEFAULT 0 CHECK(allocated_usd_micros>=0 AND allocated_usd_micros<=amount_usd_micros),settled_usd_micros INTEGER CHECK(settled_usd_micros>=0),state TEXT NOT NULL CHECK(state IN ('held','uncertain','settled','released')),pricing_snapshot_id TEXT,bound_json TEXT NOT NULL DEFAULT '{}',request_digest TEXT NOT NULL,sandbox_slot INTEGER NOT NULL DEFAULT 0 CHECK(sandbox_slot IN (0,1)),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,expires_at INTEGER,settled_at INTEGER,release_reason TEXT,revision INTEGER NOT NULL DEFAULT 1,UNIQUE(owner_scope,operation_key),UNIQUE(owner_scope,campaign_id,id),FOREIGN KEY(owner_scope,campaign_id) REFERENCES campaigns(owner_scope,id),FOREIGN KEY(owner_scope,campaign_id,parent_reservation_id) REFERENCES budget_reservations(owner_scope,campaign_id,id)) STRICT;
CREATE INDEX reservations_owner ON budget_reservations(owner_scope,campaign_id,state,created_at);
CREATE TABLE reservation_accounts(reservation_id TEXT NOT NULL,account_id TEXT NOT NULL,PRIMARY KEY(reservation_id,account_id),FOREIGN KEY(reservation_id) REFERENCES budget_reservations(id),FOREIGN KEY(account_id) REFERENCES budget_accounts(id)) STRICT;
CREATE TABLE budget_ledger_entries(id TEXT PRIMARY KEY,owner_scope TEXT NOT NULL,account_id TEXT NOT NULL,reservation_id TEXT,entry_key TEXT NOT NULL UNIQUE,category TEXT NOT NULL,reserved_delta INTEGER NOT NULL,settled_delta INTEGER NOT NULL,created_at INTEGER NOT NULL,evidence TEXT,FOREIGN KEY(account_id) REFERENCES budget_accounts(id),FOREIGN KEY(reservation_id) REFERENCES budget_reservations(id)) STRICT;
CREATE TABLE allowance_grants(id TEXT PRIMARY KEY,owner_scope TEXT NOT NULL,campaign_id TEXT NOT NULL,account_id TEXT NOT NULL,operation_id TEXT NOT NULL,old_limit INTEGER NOT NULL,new_limit INTEGER NOT NULL,pricing_snapshot_id TEXT,reason TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(owner_scope,operation_id),FOREIGN KEY(owner_scope,campaign_id) REFERENCES campaigns(owner_scope,id),FOREIGN KEY(account_id) REFERENCES budget_accounts(id)) STRICT;
CREATE TABLE campaign_events(id TEXT PRIMARY KEY,owner_scope TEXT NOT NULL,campaign_id TEXT NOT NULL,sequence INTEGER NOT NULL CHECK(sequence>0),type TEXT NOT NULL,payload_json TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(owner_scope,campaign_id,sequence),FOREIGN KEY(owner_scope,campaign_id) REFERENCES campaigns(owner_scope,id)) STRICT;
CREATE TABLE idempotency_records(id TEXT PRIMARY KEY,owner_scope TEXT NOT NULL,key TEXT NOT NULL,method TEXT NOT NULL,route TEXT NOT NULL,request_digest TEXT NOT NULL,effect_id TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(owner_scope,key),FOREIGN KEY(owner_scope) REFERENCES sessions(owner_scope)) STRICT;
CREATE TABLE operator_audit_events(id TEXT PRIMARY KEY,action TEXT NOT NULL,operation_id TEXT NOT NULL UNIQUE,reason TEXT NOT NULL,payload_json TEXT NOT NULL,created_at INTEGER NOT NULL) STRICT;
CREATE TABLE credential_revocations(owner_scope TEXT NOT NULL,credential_id TEXT NOT NULL,revoked_at INTEGER NOT NULL,PRIMARY KEY(owner_scope,credential_id),FOREIGN KEY(owner_scope,credential_id) REFERENCES credentials(owner_scope,id)) STRICT;
